package io.github.ningpp.compat;

/** Replacement for System.InsufficientMemoryException (generated by CSharpToJava converter). */
public class InsufficientMemoryException extends RuntimeException {
    public InsufficientMemoryException() { super(); }
    public InsufficientMemoryException(String message) { super(message); }
    public InsufficientMemoryException(String message, Throwable cause) { super(message, cause); }
}
